/**
 * Positioning AND anchor-relative sizing for top-layer popovers. Anchors an
 * ELEMENT; to anchor a viewport coordinate, use `useAnchoredPopoverAtPoint`.
 *
 * There are two runtime paths. Each is a function that applies its styles and
 * returns the cleanup: CSS Anchor Positioning in `./anchor-positioning`, and the
 * JavaScript fallback in `./javascript-fallback`. The hook picks the path ONCE,
 * at the top of the effect, and passes it to positioning, sizing and margins.
 *
 * See `notes/architecture/positioning.md` and
 * `notes/decisions/fit-available-space.md`.
 */
import { useMemo } from 'react';
import { useId } from '@atlaskit/ds-lib/use-id';
import { useLayoutEffect } from '@atlaskit/ds-lib/use-layout-effect';
import { applyAnchorPositioning } from './anchor-positioning/apply-anchor-positioning';
import { getAnchoredPopoverSizeDeclarations } from './anchored-popover-size';
import { isOverlapPlacement } from './is-overlap-placement';
import { applyJavaScriptFallbackPositioning } from './javascript-fallback/apply-javascript-fallback-positioning';
import { resolvePlacement } from './resolve-placement';
import { supportsAnchorPositioning } from './supports-anchor-positioning';
import { supportsAnchorSize } from './supports-anchor-size';

/**
 * Maps the popover to the adjacent side it would mostly extend toward in overlap placement.
 */
function getAdjacentFallbackPlacement(placement) {
  if (!isOverlapPlacement(placement)) {
    return placement;
  }
  return {
    ...placement,
    edge: placement.edge === 'overlap-end' ? 'start' : 'end'
  };
}

/**
 * Which way the popover's inline axis runs. Maps every physical measurement below
 * onto a logical axis: the viewport unit of each cap and the anchor's measured
 * size. A style read, not a layout read, so it is cheap enough to do for every
 * popover.
 */
function getPopoverWritingMode({
  popover
}) {
  // `String()` because not every test environment implements `writing-mode`.
  const writingMode = String(getComputedStyle(popover).writingMode);
  const isVertical = writingMode.startsWith('vertical') || writingMode.startsWith('sideways');
  return isVertical ? 'vertical' : 'horizontal';
}

/**
 * Measured stand-in for `anchor-size(self-*)`, used wherever `anchor-size()` is
 * not: the JavaScript fallback, and browsers with anchor positioning but no
 * `anchor-size()`.
 *
 * `offsetWidth` / `offsetHeight` are physical, so the axis is picked from the
 * POPOVER's `writing-mode`. Deliberately not memoized: a cached anchor size is a
 * stale one. Runs once per effect, not per frame.
 */
function measureAnchorSize({
  anchor,
  writingMode
}) {
  if (writingMode === 'vertical') {
    return {
      inline: `${anchor.offsetHeight}px`,
      block: `${anchor.offsetWidth}px`
    };
  }
  return {
    inline: `${anchor.offsetWidth}px`,
    block: `${anchor.offsetHeight}px`
  };
}
const NO_ANCHOR_SIZE = {
  inline: null,
  block: null
};
const CSS_ANCHOR_SIZE = {
  inline: 'anchor-size(self-inline)',
  block: 'anchor-size(self-block)'
};

/**
 * The anchor size that the size declarations use:
 *
 * - `NO_ANCHOR_SIZE` when no size rule reads the anchor size.
 * - `CSS_ANCHOR_SIZE` (`anchor-size()` references) when the browser supports them.
 * - Otherwise, the anchor size measured in pixels.
 */
function getAnchorSize({
  anchor,
  writingMode,
  needsAnchorSize,
  canUseAnchorSize
}) {
  if (!needsAnchorSize) {
    return NO_ANCHOR_SIZE;
  }
  if (canUseAnchorSize) {
    return CSS_ANCHOR_SIZE;
  }
  return measureAnchorSize({
    anchor,
    writingMode
  });
}
function isAnchorRelative({
  size
}) {
  return size === 'match-anchor' || size === 'min-anchor';
}

/**
 * The `anchor-name` written to an anchor that does not already carry one, as a
 * CSS `<dashed-ident>`. `useId()` is the same source as every other id in the
 * design system, including the popover's own `id` that `aria-controls` and
 * `popovertarget` point at. So it is unique exactly where those are, and collides
 * exactly where they do. See `useAnchoredPopover` for the one case that needs the
 * host's help.
 *
 * `@atlaskit/ds-lib`'s `useId` already swaps React's `:` and `«»` for `_`. The
 * replace covers a host `identifierPrefix`, which may carry characters a
 * `<dashed-ident>` cannot.
 */
function useNewAnchorName() {
  const id = useId();
  return useMemo(() => `--anchor-${id.replace(/[^A-Za-z0-9_-]/g, '_')}`, [id]);
}

/**
 * A referentially stable, fully resolved placement variant, so a new inline
 * `placement` object on each render does not re-run the effect.
 */
function useStablePlacement({
  placement
}) {
  const {
    axis,
    edge,
    align,
    offset
  } = resolvePlacement({
    placement
  });
  const {
    gap,
    crossAxisShift
  } = offset;
  const {
    value,
    direction
  } = crossAxisShift;
  return useMemo(() => ({
    axis,
    edge,
    align,
    offset: {
      gap,
      crossAxisShift: {
        value,
        direction
      }
    }
  }), [axis, edge, align, gap, value, direction]);
}

/**
 * Exported so `useAnchoredPopoverAtPoint` can forward the options it does not own.
 */

/**
 * Positions and sizes a popover relative to an anchor. Owns every inline style on
 * the popover host: where it goes, how big it is relative to its anchor, and the
 * margins that keep it clear of the anchor and the viewport edge. It knows nothing
 * about visibility or animation. Compose it with `Popover`.
 *
 * On modern browsers the browser handles flipping via CSS Anchor Positioning;
 * otherwise it falls back to measured `position: fixed` coordinates, re-run on
 * scroll and resize.
 *
 * `inlineSize` and `blockSize` both default to `'content'`. Two rules are
 * surprising: fitting one axis also fits an axis left on `'content'`, and fitting
 * either axis floors the placement axis. See `TPopoverAxisSize`.
 *
 * **Several React roots on one page.** The `anchor-name` this hook writes to an
 * anchor that has none comes from `useId()`, like every other id in the design
 * system. `useId()` is unique within a root; across roots it is unique for
 * client-rendered roots but NOT for roots that hydrate the same markup, where it
 * is derived from tree position. Two anchors carrying one name resolve to the last
 * in tree order, so a popover can attach to another root's trigger. A host that
 * hydrates more than one root must give each a distinct `identifierPrefix` (on
 * `hydrateRoot` and the matching server render). That is already required for the
 * popover's own `id`, which `aria-controls` and `popovertarget` point at, and for
 * every `aria-*` id the design system creates. A bundle with two copies of
 * `react-dom` has the same exposure for client-rendered roots.
 *
 * @example Position a popover below its trigger
 * ```tsx
 * const triggerRef = useRef<HTMLButtonElement>(null);
 * const popoverRef = useRef<HTMLDivElement>(null);
 *
 * useAnchoredPopover({
 *   anchorRef: triggerRef,
 *   popoverRef,
 *   placement: { axis: 'block', edge: 'end' },
 *   isOpen,
 * });
 * ```
 *
 * @example Match the trigger's width and keep the popover on screen
 * ```tsx
 * // What `<Popup shouldFitContainer shouldFitViewport>` maps to.
 * useAnchoredPopover({
 *   anchorRef: triggerRef,
 *   popoverRef,
 *   placement: { axis: 'block', edge: 'end' },
 *   isOpen,
 *   inlineSize: 'match-anchor',
 *   blockSize: 'max-available',
 * });
 * ```
 *
 * @example Expand an inline editor over its field
 * ```tsx
 * useAnchoredPopover({
 *   anchorRef: fieldRef,
 *   popoverRef,
 *   isOpen,
 *   placement: { axis: 'block', edge: 'overlap-start', align: 'start' },
 *   inlineSize: 'min-anchor',
 * });
 * // Match the first editor row to the field height; put actions below that row.
 * ```
 *
 * @example Switch to a cursor position mid-mount
 * ```tsx
 * // Complementary `isEnabled`, so exactly one hook owns the popover.
 * const shared = { popoverRef, placement, isOpen };
 *
 * useAnchoredPopover({ ...shared, anchorRef: triggerRef, isEnabled: !mousePosition });
 * useAnchoredPopoverAtPoint({
 *   ...shared,
 *   isEnabled: Boolean(mousePosition),
 *   getPoint: () => mousePositionRef.current,
 * });
 * ```
 */
export function useAnchoredPopover({
  anchorRef,
  popoverRef,
  placement,
  isOpen,
  isEnabled = true,
  inlineSize = 'content',
  blockSize = 'content',
  shouldPreserveInlineSize = false,
  forceFallbackPositioning = false
}) {
  // Stable for the life of the hook instance, so it follows a replacement anchor
  // element (the point hook remounts its `<div>`).
  const fallbackAnchorName = useNewAnchorName();
  const stablePlacement = useStablePlacement({
    placement
  });
  useLayoutEffect(() => {
    if (!isEnabled) {
      return;
    }
    const anchor = anchorRef.current;
    const popover = popoverRef.current;
    if (!anchor || !popover) {
      return;
    }
    const isOverlap = isOverlapPlacement(stablePlacement);
    const canUseCssPositioning = !forceFallbackPositioning && supportsAnchorPositioning();
    const canUseAnchorSize = canUseCssPositioning && supportsAnchorSize();
    // Overlap uses the adjacent fallback if native sizing is unavailable.
    const isUsingCssAnchorPositioning = isOverlap ? canUseAnchorSize : canUseCssPositioning;
    const isFitting = inlineSize === 'max-available' || blockSize === 'max-available';
    const writingMode = getPopoverWritingMode({
      popover
    });
    const needsAnchorSize = isAnchorRelative({
      size: inlineSize
    }) || isAnchorRelative({
      size: blockSize
    }) || !isOverlap && isFitting && isUsingCssAnchorPositioning;
    const anchorSize = getAnchorSize({
      anchor,
      writingMode,
      needsAnchorSize,
      canUseAnchorSize
    });
    const sizeStyles = getAnchoredPopoverSizeDeclarations({
      placement: stablePlacement,
      inlineSize,
      blockSize,
      isUsingCssAnchorPositioning,
      anchorSize,
      writingMode,
      shouldPreserveInlineSize
    });
    if (isUsingCssAnchorPositioning) {
      return applyAnchorPositioning({
        anchor,
        popover,
        placement: stablePlacement,
        sizeStyles,
        hasCrossAxisPadding: !isAnchorRelative({
          size: stablePlacement.axis === 'block' ? inlineSize : blockSize
        }),
        fallbackAnchorName
      });
    }
    return applyJavaScriptFallbackPositioning({
      anchor,
      popover,
      placement: getAdjacentFallbackPlacement(stablePlacement),
      sizeStyles
    });
  }, [isEnabled, anchorRef, popoverRef, stablePlacement, inlineSize, blockSize, shouldPreserveInlineSize, fallbackAnchorName, forceFallbackPositioning, isOpen]);
}